import os
import sys
import time
import urllib.request
import json

STATE_FILE = './target/state.json'

def load_state():
    if os.path.exists(STATE_FILE):
        try:
            with open(STATE_FILE, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Error loading state file: {e}")
    return {"completed_iterations": 0}

def save_state(state):
    try:
        with open(STATE_FILE, 'w') as f:
            json.dump(state, f)
    except Exception as e:
        print(f"Error saving state file: {e}")

def download_file(url, target_directory, notification_url):
    try:
        if not os.path.exists(target_directory):
            os.makedirs(target_directory)

        filename = os.path.basename(url)
        if not filename:
            print("Error: Unable to determine filename from URL.")
            sys.exit(1)

        filepath = os.path.join(target_directory, filename)
        urllib.request.urlretrieve(url, filepath)
        print(f"File downloaded successfully: {filepath}")
        print(f"Visit the notification URL: {notification_url}")

    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

def main():
    if len(sys.argv) < 3:
        print("Usage: python download.py <URL> <Notification_URL> [--interval=<seconds>] [--iterations=<count>] [--persist]")
        sys.exit(1)

    url = sys.argv[1]
    notification_url = sys.argv[2]
    target_directory = './target'

    # Parse optional arguments
    interval = 0
    max_iterations = 1
    persist = False

    for arg in sys.argv[3:]:
        if arg.startswith("--interval="):
            interval = int(arg.split("=")[1])
        elif arg.startswith("--iterations="):
            max_iterations = int(arg.split("=")[1])
        elif arg == "--persist":
            persist = True

    state = load_state() if persist else {"completed_iterations": 0}

    for i in range(state["completed_iterations"], max_iterations):
        print(f"Starting iteration {i + 1}...")
        download_file(url, target_directory, notification_url)
        state["completed_iterations"] = i + 1
        if persist:
            save_state(state)
        if interval > 0 and i + 1 < max_iterations:
            time.sleep(interval)

    print("All iterations completed.")

if __name__ == "__main__":
    main()

